from collections import Counter

def char_freq_top(s):
    if not s:
        return None
    freq = Counter(s)
    max_freq = max(freq.values())
    top_chars = [char for char, count in freq.items() if count == max_freq]
    return min(top_chars, key=s.index)
```

```python
def binary_search(xs, target):
    left, right = 0, len(xs) - 1
    while left <= right:
        mid = (left + right) // 2
        if xs[mid] == target:
            return mid
        elif xs[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
```

```python
def is_anagram(a, b):
    a = a.replace(' ', '').lower()
    b = b.replace(' ', '').lower()
    return sorted(a) == sorted(b)
```

```python
def balanced_brackets(s):
    stack = []
    bracket_map = {")": "(", "}": "{", "]": "["}
    for c in s:
        if c in bracket_map.values():
            stack.append(c)
        elif c in bracket_map.keys():
            if not stack or stack.pop() != bracket_map[c]:
                return False
    return not stack
```

